export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  description: string;
  image: string;
  /** Original publication date (ISO YYYY-MM-DD). Used as datePublished. */
  date: string;
  /** Optional last-edit date (ISO YYYY-MM-DD). Used as dateModified for
   *  schema.org BlogPosting and sitemap lastmod. Falls back to `date`. */
  updatedAt?: string;
  tags: string[];
  content: ContentBlock[];
}

export interface ContentBlock {
  type: "text" | "heading" | "quote" | "preface" | "component" | "faq" | "example";
  text: string;
  level?: number;
  componentId?: string;
}

function parseContent(raw: string): ContentBlock[] {
  try {
    const arr = JSON.parse(raw);
    return arr
      .filter((b: any) => ["text", "heading", "quote", "preface", "component", "faq", "example"].includes(b.ty))
      .map((b: any) => ({
        type: b.ty as ContentBlock["type"],
        text: b.te || "",
        ...(b.le ? { level: b.le } : {}),
        ...(b.cid ? { componentId: b.cid } : {}),
      }));
  } catch {
    return [{ type: "text", text: raw }];
  }
}

function extractImage(media: string): string {
  if (media.startsWith("{")) {
    try {
      return JSON.parse(media).img;
    } catch {
      return media;
    }
  }
  return media;
}

